package io.github.diodeme.ji.relay.protocol;

import com.southernstorm.noise.protocol.CipherState;
import com.southernstorm.noise.protocol.CipherStatePair;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.AtomicBoolean;

/** Ordered Noise transport frames with route-bound AD and explicit key epochs. */
public final class NoiseTransport implements AutoCloseable {
    private static final long REKEY_INTERVAL = 1L << 20;
    private final CipherStatePair states;
    private final RelayProtocol.Route route;
    private final RelayProtocol.Direction sendDirection;
    private final RelayProtocol.Direction receiveDirection;
    private final AtomicBoolean closed = new AtomicBoolean();
    private long sendCounter;
    private long receiveCounter;
    private long sendEpoch;
    private long receiveEpoch;

    NoiseTransport(CipherStatePair states, RelayProtocol.Route route, boolean initiator) {
        this.states = states;
        this.route = route;
        sendDirection = initiator ? RelayProtocol.Direction.CLIENT_TO_HOST : RelayProtocol.Direction.HOST_TO_CLIENT;
        receiveDirection = initiator ? RelayProtocol.Direction.HOST_TO_CLIENT : RelayProtocol.Direction.CLIENT_TO_HOST;
    }

    public synchronized Frame encrypt(byte[] plaintext) {
        requireOpen();
        if (plaintext == null || plaintext.length > RelayProtocol.MAX_FRAME_BYTES) {
            throw new IllegalArgumentException("Noise plaintext exceeds Relay frame limit");
        }
        maybeRekeySender();
        long counter = sendCounter;
        byte[] ciphertext = crypt(states.getSender(), true,
                RelayProtocol.routeAssociatedData(route, sendDirection, counter, sendEpoch), plaintext);
        sendCounter = Math.incrementExact(sendCounter);
        return new Frame(counter, sendEpoch, ciphertext);
    }

    public synchronized byte[] decrypt(Frame frame) {
        requireOpen();
        if (frame.counter() != receiveCounter || frame.keyEpoch() != receiveEpoch) {
            close();
            throw new SecurityException("Noise transport frame replayed or out of order");
        }
        maybeRekeyReceiver();
        try {
            byte[] plaintext = crypt(states.getReceiver(), false,
                    RelayProtocol.routeAssociatedData(route, receiveDirection, frame.counter(), frame.keyEpoch()),
                    frame.ciphertext());
            receiveCounter = Math.incrementExact(receiveCounter);
            return plaintext;
        } catch (RuntimeException failure) {
            close();
            throw failure;
        }
    }

    private void maybeRekeySender() {
        if (sendCounter > 0 && sendCounter % REKEY_INTERVAL == 0) {
            rekey(states.getSender());
            sendEpoch = Math.incrementExact(sendEpoch);
        }
    }

    private void maybeRekeyReceiver() {
        if (receiveCounter > 0 && receiveCounter % REKEY_INTERVAL == 0) {
            rekey(states.getReceiver());
            receiveEpoch = Math.incrementExact(receiveEpoch);
        }
    }

    private static void rekey(CipherState state) {
        byte[] zeros = new byte[32];
        byte[] next = new byte[48];
        try {
            state.setNonce(-1L);
            int length = state.encryptWithAd(null, zeros, 0, next, 0, zeros.length);
            if (length != 48) throw new IllegalStateException("Noise rekey produced an invalid key");
            state.initializeKey(next, 0);
        } catch (javax.crypto.ShortBufferException impossible) {
            throw new IllegalStateException(impossible);
        } finally {
            java.util.Arrays.fill(next, (byte) 0);
        }
    }

    private static byte[] crypt(CipherState state, boolean encrypt, byte[] ad, byte[] input) {
        byte[] output = new byte[encrypt ? input.length + state.getMACLength() : input.length];
        try {
            int length = encrypt
                    ? state.encryptWithAd(ad, input, 0, output, 0, input.length)
                    : state.decryptWithAd(ad, input, 0, output, 0, input.length);
            return java.util.Arrays.copyOf(output, length);
        } catch (javax.crypto.BadPaddingException failure) {
            throw new SecurityException("Noise transport authentication failed", failure);
        } catch (javax.crypto.ShortBufferException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private void requireOpen() {
        if (closed.get()) throw new IllegalStateException("Noise transport is closed");
    }

    @Override public void close() {
        if (closed.compareAndSet(false, true)) states.destroy();
    }

    public record Frame(long counter, long keyEpoch, byte[] ciphertext) {
        public Frame {
            if (counter < 0 || keyEpoch < 0 || ciphertext == null || ciphertext.length < 16
                    || ciphertext.length > RelayProtocol.MAX_FRAME_BYTES + 16) {
                throw new IllegalArgumentException("invalid Noise transport frame");
            }
            ciphertext = ciphertext.clone();
        }
        @Override public byte[] ciphertext() { return ciphertext.clone(); }
        public byte[] encode() {
            return ByteBuffer.allocate(16 + ciphertext.length).putLong(counter).putLong(keyEpoch).put(ciphertext).array();
        }
        public static Frame decode(byte[] value) {
            if (value == null || value.length < 32 || value.length > RelayProtocol.MAX_FRAME_BYTES + 32) {
                throw new IllegalArgumentException("invalid encoded Noise frame");
            }
            ByteBuffer buffer = ByteBuffer.wrap(value);
            long counter = buffer.getLong();
            long epoch = buffer.getLong();
            byte[] ciphertext = new byte[buffer.remaining()];
            buffer.get(ciphertext);
            return new Frame(counter, epoch, ciphertext);
        }
    }
}
